import{_ as a,c as o,o as t,ag as r}from"./chunks/framework.DuVOYUUM.js";const u=JSON.parse('{"title":"Tools","description":"","frontmatter":{"order":1},"headers":[],"relativePath":"projects/igvc-2024/software/tools.md","filePath":"projects/igvc-2024/software/tools.md","lastUpdated":1790647345000}'),s={name:"projects/igvc-2024/software/tools.md"};function n(i,e,l,c,h,d){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#ros-2">ROS 2</a></li><li><a href="#nav2">Nav2</a></li><li><a href="#gazebo">Gazebo</a></li><li><a href="#opencv">OpenCV</a></li></ul></nav><h2 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h2><p>ROS 2 is an open-source communications middleware that allows various sensors, applications, drivers, etc., to communicate with each other in an organized manner. Read the docs <a href="https://docs.ros.org/en/humble/" target="_blank" rel="noreferrer">here</a>.</p><h2 id="nav2" tabindex="-1">Nav2 <a class="header-anchor" href="#nav2" aria-label="Permalink to &quot;Nav2&quot;">​</a></h2><p>To create the path planning and visualization of the course, Horizon uses Nav2, a package that is part of ROS 2. This software is also open source, meaning publically available <a href="https://navigation.ros.org/" target="_blank" rel="noreferrer">documentation</a>.</p><h2 id="gazebo" tabindex="-1">Gazebo <a class="header-anchor" href="#gazebo" aria-label="Permalink to &quot;Gazebo&quot;">​</a></h2><p>Gazebo is a simulation software included in ROS 2 that allows the user to create robots, models, and worlds to interact with and simulate. Integrated into the software is also the ability to add sensors, like a depth camera, and simulate physics-based situations. The user can also import CAD models if the rudimentary shapes provided are insufficient for the detail needed. Tutorials for using Gazebo can be found <a href="https://classic.gazebosim.org/tutorials" target="_blank" rel="noreferrer">here</a></p><h2 id="opencv" tabindex="-1">OpenCV <a class="header-anchor" href="#opencv" aria-label="Permalink to &quot;OpenCV&quot;">​</a></h2><p>Horizon uses OpenCV, a library for computer vision. Mainly utilized for object detection and video processing, the library works with C and Python. There is much in terms of <a href="https://docs.opencv.org/" target="_blank" rel="noreferrer">documentation</a> and <a href="https://docs.opencv.org/4.x/d9/df8/tutorial_root.html" target="_blank" rel="noreferrer">tutorials</a> to be found on the internet including non-offical spaces.</p>',10)]))}const f=a(s,[["render",n]]);export{u as __pageData,f as default};
